    const tool = tools.find((t) => t.name === call.name);
    if (!tool) return "ERROR: unknown tool";
    let args;
    try { args = JSON.parse(call.arguments); } catch { return "ERROR: bad json"; }
    for (const k of tool.input_schema.required) if (!(k in args)) return "ERROR: missing " + k;
    for (const [k, spec] of Object.entries(tool.input_schema.properties))
      if (k in args && spec.enum && !spec.enum.includes(args[k])) return "ERROR: bad " + k;
    return impls[call.name](args);
  });
}
