function decide(status) {
  if (status >= 200 && status < 300) return "ok";
  if (status === 429 || status >= 500) return "retry";
  if (status === 401 || status === 403) return "fix_auth";
  return "fix_request";
}
function walk(stream, maxRetries) {
  let retries = 0, i = 0;
  for (; i < stream.length; i++) {
    const a = decide(stream[i]);
    if (a === "retry") {
      if (retries >= maxRetries) return { outcome: "gave_up", at: i, retries };
      retries++;
    } else {
      return { outcome: a, at: i, retries };
    }
  }
  return { outcome: "exhausted", at: i, retries };
}
const r = walk([503, 429, 500, 200], 5);
