const PRICE = { input: 3.00, cachedInput: 0.30, output: 15.00 };
function one(prefix, fresh, out, hit) {
  const inCost = hit
    ? (prefix / 1e6) * PRICE.cachedInput + (fresh / 1e6) * PRICE.input
    : ((prefix + fresh) / 1e6) * PRICE.input;
  return inCost + (out / 1e6) * PRICE.output;
}
function blended(calls) {
  let hitCost = 0, coldCost = 0;
  for (const c of calls) {
    hitCost += one(c.prefix, c.fresh, c.out, c.hit);
    coldCost += one(c.prefix, c.fresh, c.out, false);
  }
  return { hitCost, coldCost, discountPct: (1 - hitCost / coldCost) * 100 };
}
