function review(scores, policy) {
  const decisions = Object.entries(scores).map(([cat, score]) => {
    const t = policy[cat] ?? policy.default;
    if (score >= t.block) return cat + ":block";
    if (score >= t.warn) return cat + ":warn";
    return cat + ":allow";
  });
  const worst = decisions.some((d) => d.endsWith("block")) ? "block"
    : decisions.some((d) => d.endsWith("warn")) ? "warn" : "allow";
  return { decisions, worst };
}
