const classify = (s) => (s === 429 || s >= 500) ? "retry" : (s >= 400 ? "fix" : "ok");
const delayFor = (attempt, base, cap) => Math.min(cap, base * 2 ** attempt);
const priceOut = (inTok, outTok) => inTok / 1e6 * 3 + outTok / 1e6 * 15;
function readChunk(raw) {
  let text = "", stop = null;
  for (const line of raw.split("\n")) {
    if (!line.startsWith("data: ")) continue;
    const p = line.slice(6);
    if (p === "[DONE]") { stop = stop ?? "eof"; break; }
    const o = JSON.parse(p);
    if (o.delta) text += o.delta;
    if (o.stop_reason) stop = o.stop_reason;
  }
  return { text, stop };
}
function drive(attempts, maxRetries, base, cap) {
  let retries = 0, spend = 0, full = "", finalStop = null;
  const delays = [];
  for (const a of attempts) {
    const verdict = classify(a.status);
    if (verdict === "retry") {
      if (retries >= maxRetries) { finalStop = "gave_up"; break; }
      delays.push(delayFor(retries, base, cap));
      retries++;
      continue;
    }
    if (verdict === "fix") { finalStop = "client_error"; break; }
    const chunk = readChunk(a.stream);
    full += chunk.text;
    finalStop = chunk.stop;
    spend += priceOut(a.inTok, a.outTok);
    if (chunk.stop !== "mid") break;
  }
  return { text: full, stop: finalStop, retries, delays, spend };
}
const attempts = [
  { status: 503 },
  { status: 200, inTok: 1000, outTok: 20, stream: ['data: {"delta":"Hel"}','data: {"delta":"lo,"}','data: {"stop_reason":"mid"}'].join("\n") },
  { status: 200, inTok: 300, outTok: 20, stream: ['data: {"delta":" world"}','data: {"stop_reason":"end_turn"}','data: [DONE]'].join("\n") },
];
const r = drive(attempts, 3, 100, 2000);
console.log("text:", r.text);
console.log("stop:", r.stop);
console.log("retries:", r.retries, "delays:", r.delays.join(","));
console.log("cost $", r.spend.toFixed(4));
